    if i > kernel_start and lines[i].strip().startswith('def ') and '_fused_moe_lora_kernel' not in lines[i]:
        kernel_end = i
        break

if kernel_end == -1:
    kernel_end = len(lines)

# Extract the kernel function
kernel_body = ''.join(lines[kernel_start:kernel_end]).strip()

# Create the JSON output
output = {
    "vllm/lora/ops/triton_ops/fused_moe_lora_op.py": {
        "_fused_moe_lora_kernel": kernel_body
    }
}

# Write to prediction.json
with open('/prediction.json', 'w') as f:
    json.dump(output, f, indent=2)

print(f"Successfully extracted kernel function (lines {kernel_start+1}-{kernel_end})")
print(f"Kernel body length: {len(kernel_body)} characters")
